package store
import("context";"path/filepath";"testing";"github.com/LeonQin-ai/light-agent/control/internal/model")
func TestIdempotentTaskAndDispatch(t *testing.T){s,e:=Open(filepath.Join(t.TempDir(),"db"));if e!=nil{t.Fatal(e)};defer s.Close();c:=context.Background();a,e:=s.CreateAgent(c,"tenant","supervisor");if e!=nil{t.Fatal(e)};x,e:=s.CreateTask(c,a.ID,"req-1","{}");if e!=nil{t.Fatal(e)};y,e:=s.CreateTask(c,a.ID,"req-1","{}");if e!=nil{t.Fatal(e)};if x.ID!=y.ID{t.Fatal("duplicate request created a second task")};z,e:=s.ClaimNextTask(c);if e!=nil{t.Fatal(e)};if z.State!=model.TaskRunning{t.Fatalf("state=%s",z.State)};if e=s.CompleteTask(c,z.ID,"ok");e!=nil{t.Fatal(e)};z,e=s.GetTask(c,z.ID);if e!=nil||z.State!=model.TaskCompleted{t.Fatalf("task=%+v err=%v",z,e)}}
func TestFeishuEventDeduplication(t *testing.T){s,e:=Open(filepath.Join(t.TempDir(),"db"));if e!=nil{t.Fatal(e)};defer s.Close();c:=context.Background();a,d,e:=s.IngestFeishuEvent(c,"evt","ou_x","oc_y","hello");if e!=nil||d{t.Fatalf("first event: %v %v",d,e)};b,d,e:=s.IngestFeishuEvent(c,"evt","ou_x","oc_y","hello");if e!=nil||!d||a.ID!=b.ID{t.Fatalf("duplicate event not deduplicated: %v %v",d,e)}}
